function PartnerProfile({page,tab,setTab}:any){const vendor=page.group==='Vendors';const tabs=['Overview','Contacts','Addresses','Tax details',vendor?'Bank details':'Credit controls','Invoices / Bills','Receipts / Payments','Credits & refunds','Statements','Ageing','Activities'];return <div className="profile-workspace"><section className="panel partner-hero"><div className="partner-avatar">{vendor?'MS':'AL'}</div><div><small>{vendor?'VENDOR ACCOUNT':'CUSTOMER ACCOUNT'}</small><h2>{vendor?'Meridian Office Supplies':'Aster Labs Pvt Ltd'}</h2><p>{vendor?'GSTIN 29AAACM2201P1Z2':'GSTIN 32AABCA1234F1Z5'} · Kerala, India · INR</p><Badge>Active</Badge></div><div className="partner-balance"><small>{vendor?'Payable balance':'Receivable balance'}</small><b>{vendor?'₹ 34,220':'₹ 8,42,500'}</b><span>{vendor?'3 open bills':'6 open invoices'}</span></div></section><div className="tabs">{tabs.map(t=><button className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Overview'?<div className="two-columns"><section className="panel"><SectionTitle title="Account information"/><div className="details-grid"><div><small>Legal name</small><b>{vendor?'Meridian Office Supplies':'Aster Labs Pvt Ltd'}</b></div><div><small>Email</small><b>finance@example.in</b></div><div><small>Phone</small><b>+91 98765 43210</b></div><div><small>Country</small><b>India</b></div><div><small>Payment terms</small><b>Net 30</b></div><div><small>Currency</small><b>INR</b></div></div></section><section className="panel"><SectionTitle title="Finance controls"/><div className="details-grid"><div><small>Control account</small><b>{vendor?'2001 · Trade Payables':'1100 · Trade Receivables'}</b></div><div><small>Tax profile</small><b>Regular GST</b></div><div><small>Credit limit</small><b>₹ 15,00,000</b></div><div><small>Ageing risk</small><Badge>Normal</Badge></div></div></section><section className="panel span-two"><SectionTitle title="Recent financial activity"/><DataTable columns={['Date','Reference','Document','Amount','Residual','Status']} rows={ [['24 Nov','INV/0048','Invoice','₹ 1,41,600','₹ 41,600','Partially paid'],['18 Nov','RCT/018','Receipt','₹ 1,00,000','—','Posted']]}/></section></div>:<section className="panel"><SectionTitle title={tab} sub={`Manage ${tab.toLowerCase()} for this ${vendor?'vendor':'customer'} account`}/><div className="form-grid three"><label>Legal / display name<input defaultValue={vendor?'Meridian Office Supplies':'Aster Labs Pvt Ltd'}/></label><label>Email<input defaultValue="finance@example.in"/></label><label>Phone<input defaultValue="+91 98765 43210"/></label><label>Tax identifier<input defaultValue="32AABCA1234F1Z5"/></label><label>Payment terms<select><option>Net 30</option></select></label><label>Currency<select><option>INR</option></select></label></div></section>}</div>}
function ReceiptAllocation({notify}:any){const [amt,setAmt]=useState('120000');return <div className="allocation-workspace"><section className="panel"><SectionTitle title="Register customer receipt" sub="Record payment and allocate it to open receivables"/><div className="form-grid three"><label>Customer<select><option>Aster Labs Pvt Ltd</option><option>Northstar Retail</option></select></label><label>Receipt date<input type="date" defaultValue="2026-11-25"/></label><label>Payment journal<select><option>HDFC Bank</option><option>Cash</option></select></label><label>Payment method<select><option>Bank transfer</option><option>Cash</option><option>Cheque</option><option>Card</option><option>UPI</option></select></label><label>Payment reference<input placeholder="UTR / cheque / transaction ID"/></label><label>Currency<select><option>INR</option></select></label><label>Receipt amount<input type="number" value={amt} onChange={e=>setAmt(e.target.value)}/></label><label>TDS withheld<input type="number" defaultValue="0"/></label><label>Unapplied amount<input readOnly value={Math.max(0,+amt-100000)}/></label></div><SectionTitle title="Allocate to invoices" sub="One receipt may settle multiple invoices; partial allocations supported"/><DataTable columns={['Invoice','Invoice date','Due date','Original amount','Residual','Allocation']} rows={ [['INV/2026/0048','24 Nov','09 Dec','₹ 1,41,600','₹ 1,00,000','₹ 1,00,000'],['INV/2026/0047','22 Nov','07 Dec','₹ 1,00,300','₹ 1,00,300','₹ 0'],['INV/2026/0046','12 Nov','22 Nov','₹ 53,100','₹ 53,100','₹ 0']]}/><div className="allocation-summary"><div><small>Receipt amount</small><b>{money(+amt||0)}</b></div><div><small>Allocated</small><b>₹ 1,00,000</b></div><div><small>Remaining unapplied</small><b>{money(Math.max(0,(+amt||0)-100000))}</b></div><button className="btn primary" onClick={()=>notify('Receipt saved as draft; no ledger posting performed.')}>Save receipt draft</button></div></section><aside className="panel"><h3>Receipt controls</h3>{['Multiple invoice allocation','Partial payments','TDS withholding','Advance / overpayment','Reversal traceability'].map(x=><div className="check-line"><CheckCircle2 size={15}/>{x}</div>)}<div className="notice">Allocation cannot exceed receipt amount or invoice residual. Server-side validation is required.</div></aside></div>}
function PaymentWorkspace({page,notify}:any){const vendor=page.group==='Vendors';return <div className="payment-workspace"><div className="metrics three"><Metric label="Selected residuals" value="₹ 2,46,300"/><Metric label="TDS deduction" value="₹ 18,400" color="orange"/><Metric label="Net payment" value="₹ 2,27,900" color="green"/></div><section className="panel"><SectionTitle title={vendor?'Select approved bills for payment':'Refund authorization'} sub={vendor?'Due date, overdue days, discount terms and residual amount':'Original credit, source receipt and refund destination'}/><DataTable columns={vendor?['Select','Bill','Vendor','Due date','Overdue days','Residual','TDS','Pay amount']:['Refund','Customer','Credit note','Original receipt','Method','Amount','State']} rows={vendor?[['☐','BILL/031','Meridian Office Supplies','08 Dec 2026','0','₹ 34,220','₹ 0','₹ 34,220'],['☐','BILL/029','Apex Logistics','20 Nov 2026','5','₹ 18,500','₹ 1,850','₹ 16,650'],['☐','BILL/026','Kaveri Cloud Services','18 Nov 2026','7','₹ 72,000','₹ 7,200','₹ 64,800']]:[['RF/014','Aster Labs','CN/008','RCT/019','Bank transfer','₹ 18,000','Pending']]}/></section><section className="panel"><SectionTitle title={vendor?'Payment batch configuration':'Refund details'}/><div className="form-grid four"><label>Payment date<input type="date" defaultValue="2026-11-25"/></label><label>Payment method<select><option>Bank transfer</option><option>Cheque</option><option>Cash</option></select></label><label>Bank journal<select><option>HDFC Bank</option></select></label><label>Payment reference<input placeholder="Batch / UTR reference"/></label></div><div className="notice"><span>Lifecycle: Prepared → Approved → Initiated → Settled → Reconciled.</span><button className="btn primary" onClick={()=>notify('Payment prepared as draft; no external transfer initiated.')}>{vendor?'Prepare payment batch':'Save refund draft'}</button></div></section></div>}
function CreditNote({page,notify}:any){const vendor=page.group==='Vendors';return <div className="credit-workspace"><section className="panel"><SectionTitle title={vendor?'Vendor credit / debit adjustment':'Customer credit note'} sub="Link original document, reason, line details, tax reversal and amount"/><div className="form-grid three"><label>{vendor?'Vendor':'Customer'}<select><option>{vendor?'Meridian Office Supplies':'Aster Labs Pvt Ltd'}</option></select></label><label>Original {vendor?'bill':'invoice'}<select><option>{vendor?'BILL/2026/031':'INV/2026/0048'}</option></select></label><label>Adjustment date<input type="date" defaultValue="2026-11-25"/></label><label>Adjustment reason<select><option>Price adjustment</option><option>Goods returned</option><option>Service cancellation</option><option>Tax correction</option></select></label><label>Reference<input placeholder="Supplier / customer reference"/></label><label>Adjustment amount<input type="number" defaultValue="10000"/></label></div><SectionTitle title="Adjustment lines" action="Add line"/><DataTable columns={['Description','Quantity','Unit amount','Tax treatment','Tax reversal','Line total']} rows={ [['Returned / adjusted item','1','₹ 10,000','GST 18%','₹ 1,800','₹ 11,800']]}/><div className="notice warning"><AlertTriangle size={14}/>Credits exceeding the original invoice require authorised exception and reason.</div><button className="btn primary" onClick={()=>notify('Adjustment saved as draft. Posting and reconciliation are not live.')}>Save adjustment draft</button></section><aside className="panel"><h3>Adjustment summary</h3><div className="sum-row"><span>Taxable amount</span><b>₹ 10,000</b></div><div className="sum-row"><span>GST reversal</span><b>₹ 1,800</b></div><div className="sum-row total"><span>Total credit</span><b>₹ 11,800</b></div></aside></div>}
function BankAccounts(){return <div className="bank-workspace"><div className="metrics three"><Metric label="Total bank balance" value="₹ 17,42,650"/><Metric label="Unreconciled items" value="12" color="orange"/><Metric label="Last synchronization" value="Today · 08:42 AM" color="green"/></div><div className="bank-cards">{[['HDFC Bank','·· 4821','₹ 12,84,500','Synced today'],['ICICI Bank','·· 1092','₹ 4,58,150','2 transactions to reconcile'],['Main Cash Register','Cash','₹ 1,00,000','Counted yesterday']].map(x=><section className="panel"><div className="bank-card-top"><div className="bank-icon">₹</div><Badge>Active</Badge></div><h2>{x[0]}</h2><small>{x[1]} · INR</small><b className="bank-balance">{x[2]}</b><p>{x[3]}</p><div className="bank-links"><button>Transactions</button><button>Synchronize</button><button>Settings</button></div></section>)}</div><section className="panel"><SectionTitle title="Bank account configuration" sub="Provider, masked number, currency, ledger account and opening balance"/><div className="form-grid four"><label>Bank / provider<input defaultValue="HDFC Bank"/></label><label>Account number<input defaultValue="•••• •••• 4821"/></label><label>Currency<select><option>INR</option></select></label><label>Ledger account<select><option>1003 · Bank</option></select></label></div></section></div>}
function ProviderCatalogue({notify}:any){const providers=['Razorpay','Stripe','PayPal','PayU','Cashfree','Adyen','Authorize.net','Flutterwave','Mollie','Worldline','Wire Transfer','Pay on Invoice','Demonstration'];return <div className="provider-workspace"><div className="provider-intro"><div><small>PAYMENT CONNECTIVITY</small><h2>Provider catalogue</h2><p>Install, configure, test and enable a provider for a selected company and journal.</p></div><Badge>3 configured</Badge></div><div className="provider-grid">{providers.map((name,i)=><div className="provider-card"><div className="provider-logo">{name.slice(0,2).toUpperCase()}</div><div><b>{name}</b><small>{i>9?'Built-in payment method':'External payment provider'}</small><Badge>{i<3?'Configured':i>9?'Available':'Not installed'}</Badge></div><button className="btn outline small" onClick={()=>notify(`${name} setup opened. Verify country, fees and API support before enabling.`)}>{i<3?'Configure':'Install'}</button></div>)}</div><div className="notice warning"><KeyRound size={15}/>Credentials must be stored in managed secret storage, masked and access-restricted. Verify provider availability, fees and API behavior before activation.</div></div>}
function OCRReview({notify}:any){return <div className="ocr-workspace"><section className="panel document-preview"><div className="fake-invoice"><div className="fake-brand">MERIDIAN OFFICE SUPPLIES</div><h3>SUPPLIER INVOICE</h3><div className="fake-lines"><i/><i/><i/><i/></div><div className="fake-table"/><div className="fake-lines"><i/><i/></div></div><b>supplier_invoice_8821.pdf</b><small>2 pages · Uploaded 25 Nov 2026</small><button className="btn outline small"><Eye size={13}/> Preview original</button></section><section className="panel"><div className="ocr-header"><div><small>OCR EXTRACTION PROPOSAL</small><h2>Review extracted bill</h2><p>Extraction remains draft until a human confirms all fields.</p></div><Badge>Needs review</Badge></div><div className="confidence"><span>Overall extraction confidence</span><b>92%</b><div className="progress"><i/></div></div><div className="form-grid two">{[['Vendor','Meridian Office Supplies','98%'],['Supplier invoice no.','MS-8821','99%'],['Invoice date','23 Nov 2026','96%'],['Due date','08 Dec 2026','93%'],['Subtotal','₹ 29,000','95%'],['GST','₹ 5,220','91%'],['Total','₹ 34,220','99%'],['GSTIN','29AAACM2201P1Z2','88%']].map(x=><label>{x[0]}<input defaultValue={x[1]}/><small>Confidence {x[2]}</small></label>)}</div><div className="duplicate-warning"><AlertTriangle size={16}/><div><b>Duplicate check completed</b><small>No exact duplicate found. One similar supplier invoice needs confirmation.</small></div><Badge>Review</Badge></div><div className="right-actions"><button className="btn outline" onClick={()=>notify('Extraction rejected; original file retained.')}>Reject extraction</button><button className="btn primary" onClick={()=>notify('Extraction confirmed as draft bill; not posted.')}>Confirm as draft bill</button></div></section></div>}
function ReviewQueue({page,notify}:any){return <div className="review-workspace"><div className="metrics four"><Metric label="Pending approvals" value="18"/><Metric label="High priority" value="04" color="red"/><Metric label="Oldest item" value="6 days" color="orange"/><Metric label="Within SLA" value="86%" color="green"/></div><div className="tabs"><button className="active">All items 18</button><button>Invoices 6</button><button>Journal entries 4</button><button>Payments 3</button><button>Tax exceptions 2</button><button>Reconciliation 3</button></div><section className="panel"><SectionTitle title={page.id==='approval-queue'?'Approval inbox':'Review queue'} sub="Actionable, permission-filtered and traceable to source records"/><DataTable columns={['Priority','Document','Type','Requester','Amount','Submitted','Approver','Status']} rows={ [['High','BILL/2026/031','Vendor bill','Accounts Payable','₹ 34,220','Today','Finance Manager','Pending'],['High','JE/2026/048','Journal entry','Accountant','₹ 1,20,000','Yesterday','Finance Manager','Pending'],['Normal','PAY/2026/014','Vendor payment','Accounts Payable','₹ 72,000','23 Nov','Finance Manager','In review'],['Normal','GST/2B/11','Tax exception','Accountant','₹ 12,400','22 Nov','Tax reviewer','Needs review']]}/></section><div className="notice"><ShieldCheck size={15}/>Preparation, approval and final posting are separate authorities. Role and company scope determine available actions.<button className="btn outline small" onClick={()=>notify('Approval details opened')}>Open selected item</button></div></div>}
function AuditTrail({page}:any){return <div className="audit-workspace"><section className="panel"><div className="form-grid four"><label>Actor<select><option>All actors</option><option>Rahila K.</option></select></label><label>Action<select><option>All actions</option><option>Posted</option><option>Approved</option><option>Updated</option></select></label><label>Date range<input defaultValue="01 Nov – 25 Nov 2026"/></label><label>Record reference<input placeholder="Search record ID"/></label></div></section><section className="panel"><SectionTitle title={page.id==='journal-audit'?'Journal audit findings':'Audit trail'} sub={page.id==='journal-audit'?'Sequence gaps, reversals and unusual journal activity':'Actor, timestamp, action, old/new values, source and reason'}/><div className="timeline">{[['Today · 10:42','Rahila K.','Invoice draft updated','INV/2026/0048','Changed due date from 05 Dec to 09 Dec 2026 · Customer invoice workspace'],['Today · 09:18','Accounts Payable','Vendor bill uploaded','BILL/2026/031','Original supplier PDF attached · OCR extraction ID OCR-8821'],['Yesterday · 16:30','Finance Manager','Journal entry approved','JE/2026/046','Approval threshold satisfied · APR-224'],['22 Nov · 11:05','Rahila K.','Bank match confirmed','STMT-1019','Matched UPI/BLUEPEAK with receipt RCT/018 · Rule version MATCH-1.2']].map(x=><div className="timeline-item"><div className="timeline-marker"><History size={14}/></div><div><div><b>{x[2]}</b><small>{x[0]}</small></div><span>{x[1]} · {x[3]}</span><p>{x[4]}</p></div></div>)}</div></section></div>}
function WorkingFiles(){return <div className="files-workspace"><section className="panel file-upload"><FolderOpen size={30}/><h2>Finance working files</h2><p>Controlled working papers, supporting evidence, tax schedules and period-close documents.</p><button className="btn primary"><Upload size={14}/> Upload working paper</button></section><div className="file-folders">{[['Period close','12 files','Close checklist and reconciliations'],['Tax compliance','8 files','GST workpapers and schedules'],['Annual reports','5 files','Financial statements and audit schedules'],['Reconciliation evidence','18 files','Bank statements and match support']].map(x=><section className="panel"><FolderOpen size={19}/><b>{x[0]}</b><strong>{x[1]}</strong><small>{x[2]}</small></section>)}</div><section className="panel"><SectionTitle title="Recent files" sub="Version, owner, source and access history"/><DataTable columns={['File','Category','Period','Owner','Version','Updated','Access']} rows={ [['bank-recon-nov.xlsx','Reconciliation','Nov 2026','Rahila K.','v3','Today','Finance team'],['gst-gstr3b-nov.pdf','Tax compliance','Nov 2026','Tax reviewer','v2','Yesterday','Restricted'],['annual-close-notes.docx','Period close','FY 2026–27','Finance Manager','v1','20 Nov','Finance team']]}/></section></div>}
function PeriodClose({notify}:any){const tasks=[['Review unposted entries','Accountant','5 items remain','In progress'],['Reconcile bank accounts','Treasury','2 unreconciled lines','In progress'],['Reconcile customer/vendor ledgers','AR / AP','Control account check','Pending'],['Post accruals and regularization','Accountant','No draft adjustment','Pending'],['Process depreciation','Fixed assets','12 assets due','Pending'],['Review deferred schedules','Accountant','4 schedules','Pending'],['Review inventory valuation','Inventory / Finance','Awaiting stock valuation event','Blocked'],['Validate financial reports','Finance Manager','Trial balance and statements','Pending'],['Apply fiscal lock dates','Finance Manager','After close approval','Locked']];return <div className="close-workspace"><section className="close-banner"><div><small>PERIOD CLOSE · NOVEMBER 2026</small><h2>Month-end close checklist</h2><p>Required reconciliations and review tasks must be complete before closing.</p></div><div><b>2 / 9</b><small>Tasks complete</small><div className="progress"><i style={{width:'22%'}}/></div></div></section><div className="two-columns"><section className="panel"><SectionTitle title="Close tasks" sub="Owners, dependencies and evidence"/>{tasks.map((t,i)=><div className="close-task"><div className={i<2?'checked':''}>{i<2?<Check size={13}/>:i===6?<LockKeyhole size={13}/>:i+1}</div><span><b>{t[0]}</b><small>{t[1]} · {t[2]}</small></span><Badge>{t[3]}</Badge><button className="more"><ArrowUpRight size={14}/></button></div>)}</section><section className="panel"><h3>Close controls</h3>{[['Trial balance','Needs review'],['Bank reconciliation','In progress'],['AR / AP control accounts','Pending'],['Tax period lock','Not applied']].map(x=><div className="sum-row"><span>{x[0]}</span><Badge>{x[1]}</Badge></div>)}<button className="btn primary full" onClick={()=>notify('Close readiness validation started (prototype).')}>Validate close readiness</button><div className="notice warning">Hard lock requires authorised approval, reason and immutable audit evidence.</div></section></div></div>}
function Regularization({notify}:any){return <section className="panel"><SectionTitle title="Period regularization entry" sub="Controlled correction with evidence and approval"/><div className="form-grid three"><label>Adjustment period<select><option>November 2026</option></select></label><label>Accounting date<input type="date" defaultValue="2026-11-30"/></label><label>Adjustment type<select><option>Accrual</option><option>Reclassification</option><option>Correction</option></select></label><label>Reason<input placeholder="Required business reason"/></label><label>Source reference<input placeholder="Affected document / account"/></label><label>Prepared by<input defaultValue="Rahila K."/></label></div><SectionTitle title="Adjustment journal lines" action="Add line"/><DataTable columns={['Account','Partner','Narration','Debit','Credit']} rows={ [['5001 · Office Expenses','—','Accrued expense','₹ 25,000','—'],['2100 · Accrued Liabilities','—','Accrual liability','—','₹ 25,000']]}/><div className="upload-box"><Paperclip size={14}/>Attach supporting schedule / evidence</div><div className="notice">The adjustment must balance, retain the source/period link, pass approval and preserve immutable audit history.</div><button className="btn primary" onClick={()=>notify('Adjustment saved as draft; no journal posted.')}>Save adjustment draft</button></section>}
