 if(id==='rounding-checks') return <section className="panel"><SectionTitle title="Rounding and payment checks" sub="Deterministic rounding policy and validation controls"/><div className="form-grid three"><label>Currency precision<select><option>2 decimal places</option><option>0 decimal places</option><option>4 decimal places</option></select></label><label>Tax rounding method<select><option>Per line</option><option>Per tax group</option><option>Global</option></select></label><label>Rounding strategy<select><option>Half up</option><option>Half even</option></select></label><label>Cheque amount tolerance<input defaultValue="0.01"/></label><label>Payment difference account<select><option>999001 · Cash Difference Gain</option></select></label><label>Allow manual override<select><option>Finance Manager only</option><option>Disabled</option></select></label></div></section>;
