function Directory({page,query}:any){const rows=samples[page.id]||Array.from({length:5},(_,i)=>[`${page.label.slice(0,3).toUpperCase()}-${2026+i}`,['Aster Labs Pvt Ltd','Northstar Retail','Meridian Office Supplies'][i%3],'24 Nov 2026','₹ 1,20,000',['Active','Pending','Review'][i%3]]);const columns=page.id==='customer-directory'?['Customer','Type','GSTIN / PAN','Payment terms','Receivable balance','Status']:page.id==='vendor-directory'?['Vendor','Type','GSTIN / PAN','Payment terms','Payable balance','Status']:page.id==='customer-invoices'?['Invoice','Customer','Invoice date','Due date','Untaxed amount','Total','Amount due','Status']:['Bill','Vendor','Supplier invoice','Bill date','Due date','Total','Amount due','Status'];return <><div className="metrics three"><Metric label={page.group==='Customers'?'Active customers':'Active vendors'} value={page.group==='Customers'?'128':'86'}/><Metric label="Outstanding balance" value={page.group==='Customers'?'₹ 6,28,500':'₹ 3,14,800'} color="orange"/><Metric label="Needs attention" value="06" color="blue"/></div><section className="panel"><div className="list-tools"><div className="search-inline"><Search size={14}/><input placeholder={`Search ${page.label.toLowerCase()}`} value={query}/></div><select><option>All records</option><option>Active</option><option>Needs attention</option><option>Archived</option></select><button className="btn outline small"><Filter size={13}/> Filters</button><button className="btn outline small"><SlidersHorizontal size={13}/> Columns</button></div><DataTable columns={columns} rows={rows.filter(r=>r.join(' ').toLowerCase().includes(query.toLowerCase()))}/><div className="table-footer">Showing records · Company scoped <span>‹　1　2　3　›</span></div></section></>}
function GenericPage({page}:any){return <div className="generic-workspace"><section className="panel"><div className="generic-intro"><div className="generic-icon"><Layers size={23}/></div><div><small>{page.group.toUpperCase()} WORKSPACE</small><h2>{page.label}</h2><p>{page.desc}</p></div></div><div className="form-grid three"><label>Name / reference<input placeholder="Enter name or reference"/></label><label>Effective date<input type="date" defaultValue="2026-11-25"/></label><label>Company scope<select><option>Northstar Industries</option></select></label><label>Status<select><option>Active</option><option>Draft</option><option>Archived</option></select></label><label>Description<input placeholder="Enter description"/></label><label>Owner<select><option>Rahila K.</option></select></label></div><button className="btn primary">Save draft</button></section><section className="panel"><SectionTitle title="Existing records" sub="Search, filter and inspect records in this workspace"/><DataTable columns={['Reference','Name / description','Effective date','Company','Owner','Status']} rows={ [['FIN-2026-014','Sample record','01 Apr 2026','Northstar Industries','Rahila K.','Active'],['FIN-2026-013','Prior record','01 Apr 2025','Northstar Industries','Finance Manager','Archived']]}/></section><div className="notice"><Info size={14}/>The source specification does not fully define all field-level behavior for this destination. Confirm business rules rather than inventing them.</div></div>}
function CreateModal({page,close,save}:any){return <div className="modal-shade" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal"><div className="modal-header"><div><small>CREATE · {page.group.toUpperCase()}</small><h2>{page.action||'New record'}</h2></div><button onClick={close}><X size={18}/></button></div><div className="modal-body"><div className="form-grid two"><label>Name / reference<input placeholder="Enter name or reference"/></label><label>Date<input type="date" defaultValue="2026-11-25"/></label><label>Company<select><option>Northstar Industries</option></select></label><label>Currency<select><option>INR</option></select></label><label>Amount<input type="number" placeholder="0.00"/></label><label>Status<select><option>Draft</option><option>Pending review</option></select></label><label className="span-two">Description / reason<textarea rows={3}/></label></div><div className="notice"><LockKeyhole size={14}/>Prototype only: this action does not post a real financial transaction.</div></div><div className="modal-actions"><button className="btn outline" onClick={close}>Cancel</button><button className="btn outline" onClick={()=>save(page.label+' draft')}>Save draft</button><button className="btn primary" onClick={()=>save(page.label+' created')}>Create record</button></div></div></div>}
